const q     = $input.all()[0].json.query || {};
const sd    = $getWorkflowStaticData('global');
let reports = sd.reports || [];

// Filtrer par date si demandé
if (q.date) reports = reports.filter(r => r.date === q.date);

// Trier du plus récent au plus ancien
reports = [...reports].sort((a, b) => b.date.localeCompare(a.date));

return [{ json: { reports, total: reports.length } }];

// ── Sécurité : vérifier le header secret ──────────────────────────
const headers = $input.all()[0].json.headers || {};
const SECRET  = 'seniorassist-2026';
if (headers['x-seniorassist-key'] !== SECRET) {
  return [{ json: { ok: false, error: 'Unauthorized' } }];
}

// ── Extraire le body ───────────────────────────────────────────────
const body       = $input.all()[0].json.body || $input.all()[0].json;
const report     = body.report     || '';
const eventCount = body.event_count !== undefined ? Number(body.event_count) : null;
const camera     = body.camera     || 'zosi';

// ── Construire l'entrée enrichie ───────────────────────────────────
const now      = new Date();
const dateStr  = now.toISOString().split('T')[0];
const dateLabel = now.toLocaleDateString('fr-FR', {
  day: '2-digit', month: '2-digit', year: 'numeric'
});

const entry = {
  id:          now.getTime(),           // timestamp ms = ID unique
  date:        dateStr,                  // "2026-03-20"
  dateLabel:   dateLabel,               // "20/03/2026"
  generatedAt: now.toISOString(),       // heure exacte
  camera:      camera,                  // "zosi"
  event_count: eventCount,              // nb détections (null si non fourni)
  report:      report                   // texte complet
};

// ── Persistance avec rotation 90 rapports ─────────────────────────
const sd = $getWorkflowStaticData('global');
if (!sd.reports) sd.reports = [];

// 1 rapport par jour (remplace si même date)
const idx = sd.reports.findIndex(r => r.date === dateStr);
if (idx >= 0) {
  sd.reports[idx] = entry;
} else {
  sd.reports.unshift(entry);
}

// Rotation : garder max 90 rapports
if (sd.reports.length > 90) {
  sd.reports = sd.reports.slice(0, 90);
}

return [{ json: { ok: true, date: dateStr, total: sd.reports.length } }];
